original:
@plo:   clc
        adc rc_w
        deca

proposal:
@hcopy: lda GATHERL,x               ; no: the stored row -- (k&7)<<5 with this run's
        eor rowoff                  ; char offset less the row's 32: rowoff's bits
        and #$E0                    ; outside $E0 through the two eors
        eor rowoff
        bcs @tpsta                  ; (always: C is set at every entry to @run)
@full:  lda GATHERL,x
  .endif
        ora rowoff                  ; (a full tile's lo byte is (id&3)<<6: bits 0-5 clear)
@tpsta: sta tp
@tpset:

        ldx wfine
        lda @ftab-2,x               ; the branch displacement for this wfine
        sta @fjmp+1
        ldx cnt                     ; char counter in X: dex/beq is 3 cycles cheaper
@fjmp:  bne @g4                     ; patched; always taken: Z = 0 at every arrival
@ftab:  .byte @g4-@ftab, 0, @g2-@ftab, 0, @g0-@ftab   ; wfine 2: six lines, 4: four, 6: two

original:
@e0:    lda SECTAB+6,x
        clc
        adc #BARLEAD

@l:     ldy lidx
        lda DIRTYLIST,y
        stza rc_x+1

proposal:
@l:     stz rc_x+1                  ; A is dead here: loaded just below
        ldy lidx
        lda DIRTYLIST,y

original:
@nokill:
        lda health
        bne @alive
        jmp player_dead
@alive: jmp player_update

proposal:
        and #K_LEFT                 ; A = 1 left, 0 right: the facing flag
        sta facing
        beq @right
        sub16 vx, t16
        bra @run
@right: add16 vx, t16
@run:   lda #1
        sta running
        bne @hmove                  ; Z = 0 from the load
@norun: stz running                 ; A dead: @hmove reloads it

original:
@run:   lda #1
        sta running
        bra @hmove
@norun: stza running

proposal:
@run:   lda #1
  .if ::MODELB
        bne @strun                  ; A = 1
@norun: lda #0                      ; A is dead: @hmove reloads it
@strun: sta running
  .else
        sta running
        bra @hmove
@norun: stz running                 ; A is dead: @hmove reloads it
  .endif

original:
@draw:  lda fe
        cmp #2
        bcc @f0
        cmp #4
        bcc @f2
        cmp #6
        bcc @f0
        lda #65
        bra @fr
@f0:    lda #61
        bra @fr
@f2:    lda #63
@fr:    sta q1

        lda #6
        clc                         ; only this arm reaches @fr with C set (cmp #9
        bra @fr                     ; fell through); @f2 and @f4 got here on a bcc
@f0:    lda fc
        bra @sp
@f2:    lda #2
        bra @fr
@f8:    lda #8
        bra @sp

proposal:
        lda #5                      ; C = 1 (cmp #9 fell through): 5 + fc + 1 at @fr
        bcs @fr                     ; always; @f2 and @f4 reach @fr on a bcc, C = 0
@f0:    lda fc
        bcc @sp                     ; always: @f0 is reached on a bcc
@f2:    lda #2
        bcc @fr                     ; always: @f2 is reached on a bcc (C = 0 for the adc)
@f8:    lda #8
        bne @sp                     ; always

@sp:    ldx otype                   ; the frame stays in A: no round trip through q1
        clc                         ; otype is 5 or 6 (the dispatch table's two
        adc @wbase-5,x              ; ob_walker entries): + 67 for 5, + 76 for 6
        jmp m_addsprite
@wbase: .byte 67, 76

original:
        bra @wxok
@wx0:   stz wx
        stz wx+1

@wy0:   stza wy
        stza wy+1
@wyok:  rts

proposal:
  .if MODELB
@wy0:   lda #0                      ; (A is dead: the caller's setbank reloads it)
        sta wy
        sta wy+1
  .else
@wy0:   stza wy
        stza wy+1
  .endif
@wyok:  rts

original:
@none:  sec
        rts
@found: clc
        rts

@end:   lda PB_LVL
        jsr pgbank
        rts

@rom:   lda ROMTYPE,x               ; the MOS's ROM type table: service ROMs only
        and #$80
        beq @nextrom
